#!/usr/bin/env node
/**
 * Build a synthetic session archive and render the committed previews from it.
 *
 *   node scripts/make-demo.mjs                       # -> .demo/sessions + docs/preview-*.html
 *   node scripts/make-demo.mjs --out .demo/sessions --keep-archive
 *
 * Why this exists: the hero screenshot in the README is generated by this
 * plugin from session logs, and real logs contain real things people typed. A
 * public repo must not ship someone's chat. So everything under `docs/` is
 * rendered from this deterministic, obviously-fictional dataset instead — same
 * shapes, same pipeline, zero private text.
 *
 * The dataset is deliberately "rich" rather than minimal: three calendar years
 * of work, multi-step turns (speak → tool → speak), a reasoning model, a few
 * subagent sessions, failed/interrupted turns, one late-night marathon, and a
 * nine-day sprint — so every badge, card and sentence layer on the page has
 * something real to point at instead of a placeholder.
 *
 * The generator writes each log as TWO zstd frames on purpose: that is how the
 * harness appends, and it keeps the multi-frame reader on the demo path too.
 */

import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import zlib from 'node:zlib';

const DEFAULT_OUT = '.demo/sessions';
const TZ = 480; // +08:00
const DAY = 24 * 60 * 60 * 1000;
const HOUR = 60 * 60 * 1000;

function arg(name, fallback = null) {
  const index = process.argv.indexOf(`--${name}`);
  return index >= 0 && process.argv[index + 1] ? process.argv[index + 1] : fallback;
}

const outRoot = arg('out', DEFAULT_OUT);
const keepArchive = process.argv.includes('--keep-archive');

/** Deterministic PRNG so regenerating the demo yields byte-identical input. */
function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = mulberry32(20261030);
const pick = (list) => list[Math.floor(random() * list.length)];
const between = (min, max) => min + Math.floor(random() * (max - min + 1));
const chance = (p) => random() < p;

