/**
 * Draw without replacement until the bag empties, then reshuffle. Random
 * picks alone make the highlight cards repeat the same title two or three
 * times in a year; a bag keeps the story varied like real work would be.
 */
function bagPicker(list) {
  let bag = [];
  return () => {
    if (bag.length === 0) bag = list.slice();
    const index = Math.floor(random() * bag.length);
    return bag.splice(index, 1)[0];
  };
}

const nextScenario = bagPicker(SCENARIOS);
/**
 * Highlight cards show the six busiest sessions, so two identical titles in
 * the same month read like a bug. Skip ahead in the bag until the title has
 * not appeared in the last few sessions.
 */
const recentTitles = [];
function takeScenario() {
  let scenario = nextScenario();
  for (let guard = 0; guard < 6 && recentTitles.includes(scenario.title); guard += 1) {
    scenario = nextScenario();
  }
  recentTitles.unshift(scenario.title);
  recentTitles.length = Math.min(recentTitles.length, 6);
  return scenario;
}

const FAILURE_REASONS = [
  { error: { message: 'tool timeout: pwsh exited 124 after 120s' } },
  { error: { message: 'model stream aborted: upstream reset by peer' } },
  { error: { message: 'context window exceeded (131072 tokens)' } },
  { error: { message: 'edit conflict: file changed on disk since read' } },
];

const REASONING = [
  '先确认是不是时序问题，再决定改等待还是改结构。',
  '把失败面拆成「输入、状态、时序」三类，逐个排除。',
  '先算一遍量级，避免为一个不会发生的情况写分支。',
  '保持对外结构不变，只改内部实现，降低回滚成本。',
];

/**
 * One prompt usually yields several assistant messages: a short "let me look"
 * step, the tool calls, then the actual answer. Counting only the spoken ones
 * is what makes the human-vs-AI ratio read like a real session instead of 1:1.
 */
const AI_STEPS = [
  '先看一下这里的文件结构和调用链。',
  '我先按读到的实现定位，再决定改哪一层。',
  '跑一遍现有测试，确认改动前的基线。',
  '定位到了，改动集中在两个文件。',
  '改完再跑一次，确认没有连带影响。',
  '再看一处调用方，避免只改了一半。',
  '把中间值打出来对比一下，确认不是偶发。',
];

/** Local wall clock at +08:00 → epoch ms. */
function localMs(year, month, day, hour, minute) {
  return Date.UTC(year, month - 1, day, hour, minute) - TZ * 60_000;
}

function makeSession(index, start, workspace, scenario, kind) {
  const id = `demo-${String(index).padStart(3, '0')}`;
  const model = pick(MODELS);
  const isSubagent = kind === 'subagent';
  const isMarathon = kind === 'marathon';
  const header = {
    type: 'session',
    id,
    createdAt: start,
    cwd: workspace.cwd,
    agentPreset: scenario.preset ?? pick(PRESETS),
  };
  if (isSubagent) {
    header.origin = 'subagent';
    header.delegationDepth = 1;
  }
  const rows = [
    header,
    { type: 'session/title', time: start + 900, data: { title: scenario.title } },
    { type: 'model/selection', time: start + 1_200, data: model },
  ];
  // Injected context is normal in a real log; it must never be counted as a
  // human message, so throw one in to keep that rule exercised by the demo.
  if (chance(0.16)) {
    rows.push({
      type: 'user/message',
      time: start + 1_400,
      data: { content: [{ type: 'text', text: 'AGENTS.md: 本仓库要求提交前跑单测。' }], source: { kind: 'agent' } },
    });
  }

  const turns = isSubagent
    ? scenario.turns.slice(0, Math.min(2, scenario.turns.length))
    : scenario.turns;
  const marathonTurns = isMarathon ? 11 : turns.length;
  const willFail = !isSubagent && chance(0.2);
  const failAt = willFail ? between(1, Math.max(1, Math.floor(marathonTurns / 2))) : -1;

  let cursor = start;
  for (let step = 0; step < marathonTurns; step += 1) {
    const turn = turns[step % turns.length];
    // A marathon is a sitting: gaps stay under the 30-minute "still working"
    // threshold, so the report can call out one 4-hour run.
    const gap = isMarathon ? between(17 * 60, 26 * 60) : between(25, 320);
    cursor += gap * 1_000;
    rows.push({ type: 'turn/start', time: cursor, data: {} });
    rows.push({
      type: 'user/message',
      time: cursor,
      data: { content: [{ type: 'text', text: turn.h }], source: { kind: 'user' } },
    });

    const replies = turn.a.length ? turn.a : ['看了一下，问题在这一步，我改完再同步。'];
    const stepCount = between(1, 3);
    for (let pass = 0; pass < stepCount; pass += 1) {
      cursor += between(5, 22) * 1_000;
      rows.push({
        type: 'assistant/message',
        time: cursor,
        data: {
          message: { content: [{ type: 'text', text: pick(AI_STEPS) }] },
          usage: { inputTokens: between(18_000, 62_000), cacheReadTokens: between(4_000, 34_000), outputTokens: between(30, 90) },
        },
      });
      const calls = between(1, Math.min(3, turn.tools.length || 1));
      for (let call = 0; call < calls; call += 1) {
        cursor += between(4, 42) * 1_000;
        rows.push({ type: 'tool/call', time: cursor, data: { name: pick(turn.tools.length ? turn.tools : TOOLS) } });
      }
    }
    for (let reply = 0; reply < replies.length; reply += 1) {
      cursor += between(9, 58) * 1_000;
      const text = replies[reply];
      const content = [{ type: 'text', text }];
      if (model.model === 'deepseek-reasoner' && reply === 0) {
        content.unshift({ type: 'reasoning', text: pick(REASONING) });
      }
      rows.push({
        type: 'assistant/message',
        time: cursor,
        data: {
          message: { content },
          usage: {
            inputTokens: between(18_000, 62_000),
            cacheReadTokens: between(4_000, 34_000),
            outputTokens: Math.round(text.length * between(1, 2)),
          },
          ...(chance(0.03) ? { interrupted: true } : {}),
        },
      });
    }
    cursor += between(2, 18) * 1_000;
    rows.push({ type: 'turn/end', time: cursor, data: step === failAt ? { reason: pick(FAILURE_REASONS) } : {} });
    rows.push({ type: 'step/end', time: cursor, data: {} });
  }
  return { id, rows };
}

/**
 * Two frames, exactly like an interrupted-then-resumed writer would leave.
 * The reader has to walk both; a single-frame demo would never prove that.
 */
function writeLog(dir, rows) {
  mkdirSync(dir, { recursive: true });
  const lines = rows.map((row) => JSON.stringify(row));
  const half = Math.ceil(lines.length / 2);
  const parts = [lines.slice(0, half), lines.slice(half)]
    .filter((part) => part.length)
    .map((part) => zlib.zstdCompressSync(Buffer.from(`${part.join('\n')}\n`, 'utf8')));
  writeFileSync(join(dir, 'session.v3.jsonl.zstd'), Buffer.concat(parts));
}

/**
 * Work calendar: weekdays mostly, weekends rarely, a ten-day sprint in each
 * year (so a streak badge is real), and one long night per year (so the
 * marathon card and the late-hour card both have a true source).
 */
function buildArchive(root) {
  rmSync(root, { recursive: true, force: true });
  mkdirSync(root, { recursive: true });
  const sprints = [
    localMs(2024, 3, 4, 0, 0),
    localMs(2025, 8, 11, 0, 0),
    localMs(2026, 5, 11, 0, 0),
  ];
  const marathons = new Map([
    [localMs(2024, 11, 6, 0, 0), LONG_SCENARIOS[0]],
    [localMs(2025, 2, 19, 0, 0), LONG_SCENARIOS[2]],
    [localMs(2026, 7, 15, 0, 0), LONG_SCENARIOS[1]],
  ]);
  const start = localMs(2024, 1, 1, 0, 0);
  const end = localMs(2026, 10, 29, 0, 0);

  let index = 0;
  let sessions = 0;
  const counts = { normal: 0, marathon: 0, subagent: 0 };

  for (let day = start; day <= end; day += DAY) {
    const clock = new Date(day + TZ * 60_000);
    const year = clock.getUTCFullYear();
    const month = clock.getUTCMonth() + 1;
    const date = clock.getUTCDate();
    const weekday = clock.getUTCDay();
    const inSprint = sprints.some((sprint) => day >= sprint && day < sprint + 9 * DAY);
    const marathon = marathons.get(day);
    // Usage grows year over year, so the year-over-year delta is not noise.
    const yearFactor = year === 2024 ? 0.62 : year === 2025 ? 0.86 : 1;
    const weekend = weekday === 0 || weekday === 6;
    const active = Boolean(marathon) || inSprint || chance((weekend ? 0.07 : 0.26) * yearFactor);
    if (!active) continue;

    const perDay = marathon ? 1 : inSprint ? between(1, 2) : chance(0.24) ? 2 : 1;
    for (let slot = 0; slot < perDay; slot += 1) {
      const workspace = pick(WORKSPACES);
      const startHour = marathon
        ? between(20, 21)
        : chance(0.16)
          ? between(21, 23)
          : between(9, 19);
      const at = localMs(year, month, date, startHour, between(0, 59)) + slot * between(1, 3) * HOUR;

      if (marathon) {
        const scenario = marathon;
        const made = makeSession(index, at, workspace, scenario, 'marathon');
        writeLog(join(root, workspace.slug, made.id), made.rows);
        index += 1;
        sessions += 1;
        counts.marathon += 1;
        continue;
      }

      const scenario = takeScenario();
      const made = makeSession(index, at, workspace, scenario, 'normal');
      writeLog(join(root, workspace.slug, made.id), made.rows);
      index += 1;
      sessions += 1;
      counts.normal += 1;

      // A delegated session lands in the same workspace, a few minutes later.
      if (chance(0.1)) {
        const sub = {
          title: `子代理 · ${scenario.title}（${pick(['查文献', '跑一遍单测', '扫全仓库引用', '对比两个实现'])}）`,
          turns: scenario.turns.slice(0, 1),
          preset: 'reviewer',
        };
        const delegated = makeSession(index, at + between(3, 12) * 60 * 1_000, workspace, sub, 'subagent');
        writeLog(join(root, workspace.slug, delegated.id), delegated.rows);
        index += 1;
        sessions += 1;
        counts.subagent += 1;
      }
    }
  }
  console.log(`  ${counts.normal} normal · ${counts.marathon} marathon · ${counts.subagent} subagent`);
  return sessions;
}

function run(args) {
  const result = spawnSync(process.execPath, args, { stdio: 'inherit' });
  if (result.status !== 0) throw new Error(`command failed: node ${args.join(' ')}`);
}

const sessions = buildArchive(outRoot);
console.log(`wrote ${sessions} synthetic sessions to ${outRoot} (timezone +08:00)`);

const common = ['--archive', outRoot, '--tz', String(TZ)];
run(['bin/unwrapped.js', ...common, '--period', 'year', '--key', '2026', '--embed', '13', '--out', 'docs/preview-year.html', '--json', 'docs/preview-year.json']);
run(['bin/unwrapped.js', ...common, '--period', 'quarter', '--key', '2026-Q3', '--embed', '8', '--out', 'docs/preview-quarter.html']);
run(['bin/unwrapped.js', ...common, '--period', 'month', '--key', '2020-01', '--embed', '12', '--out', 'docs/preview-empty.html']);

if (!keepArchive) rmSync(outRoot, { recursive: true, force: true });
console.log('\npreviews rebuilt from synthetic data. next: node scripts/shot.mjs --file docs/preview-year.html --out docs/preview-year.png');
